namespace mod_videotrack\external;

defined('MOODLE_INTERNAL') || die();

global $CFG;
require_once($CFG->dirroot . '/mod/videotrack/lib.php');

use core_external\external_api;

/**
 * Shared helpers for VideoTrack external AJAX endpoints.
 *
 * @package   mod_videotrack
 * @copyright 2026 videotrack contributors
 * @license   https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
class helper extends external_api {
    /**
     * Requires the Moodle session key for browser-originated AJAX mutations.
     *
     * The activity external functions are intended for authenticated Moodle UI
     * calls. Keeping the check in one helper makes the CSRF requirement explicit
     * and consistent across segment, reaction, note, bookmark and integrity endpoints.
     *
     * @throws \moodle_exception
     */
    public static function require_ajax_sesskey(): void {
        require_sesskey();
    }

    /**
     * Validates a positive database identifier received by an AJAX endpoint.
     *
     * @param int $id Candidate id.
     * @param string $name Parameter name for diagnostics.
     * @return int Validated id.
     * @throws \invalid_parameter_exception
     */
    public static function validate_positive_id(int $id, string $name): int {
        if ($id <= 0) {
            throw new \invalid_parameter_exception('Invalid ' . $name);
        }
        return $id;
    }

    /**
     * Validates a browser playback session id generated by the AMD player.
     *
     * The client generates 32 hex characters when Web Crypto is available.
     * The legacy fallback always pads at least 16 base36 characters after the
     * sess prefix. Accepting only these bounded formats prevents callers from
     * using arbitrary long or structured identifiers in tracking and interaction
     * records.
     *
     * @param string $sessionid Session identifier from the AJAX request.
     * @return string The validated session id.
     * @throws \invalid_parameter_exception
     */
    public static function validate_session_id(string $sessionid): string {
        if (preg_match('/^(?:[a-f0-9]{32}|sess[0-9a-z]{16,48})$/', $sessionid) !== 1) {
            throw new \invalid_parameter_exception('Invalid session ID');
        }
        return $sessionid;
    }

    /**
     * Validate a per-request idempotency identifier.
     *
     * @param string $requestid Candidate request identifier.
     * @return string Validated identifier.
     */
    public static function validate_request_id(string $requestid): string {
        $requestid = trim($requestid);
        if (!preg_match('/^(?:[a-f0-9]{32}|(?:req[a-z0-9]{16,61}|sess[a-z0-9]{16,60})|restore[a-f0-9]{32,57})$/i', $requestid)) {
            throw new \invalid_parameter_exception('Invalid request identifier');
        }
        return substr($requestid, 0, 64);
    }

    /**
     * Validates the reason used to close a viewing segment.
     *
     * @param string $endreason Segment end reason.
     * @return string Validated reason.
     * @throws \invalid_parameter_exception
     */
    public static function validate_end_reason(string $endreason): string {
        // Keep this list aligned with SAVE_REASONS in amd/src/core/segment.js.
        $allowed = [
            'heartbeat', 'pause', 'seek', 'ended', 'beforeunload', 'pagehide', 'tab',
            'visibilitychange', 'reaction', 'note', 'bookmark', 'interaction',
        ];
        if (\core_text::strlen($endreason) > 32 || !in_array($endreason, $allowed, true)) {
            throw new \invalid_parameter_exception('Invalid segment end reason');
        }
        return $endreason;
    }

    /**
     * Validates that a float-like parameter is finite and inside a bounded range.
     *
     * @param float $value Value to validate.
     * @param string $name Parameter name for diagnostics.
     * @param float $min Minimum accepted value.
     * @param float $max Maximum accepted value.
     * @return float Rounded validated value.
     * @throws \invalid_parameter_exception
     */
    public static function validate_bounded_float(float $value, string $name, float $min, float $max): float {
        if (!is_finite($value) || $value < $min || $value > $max) {
            throw new \invalid_parameter_exception('Invalid ' . $name);
        }
        return round($value, 3);
    }

    /**
     * Loads the activity and validates login, context and view capability.
     *
     * @param int $cmid Course module id.
     * @return array{course: \stdClass, videotrack: \stdClass, cm: \cm_info, context: \context_module}
     */
    public static function load_and_validate_context(int $cmid): array {
        global $DB;

        $cmraw = get_coursemodule_from_id('videotrack', $cmid, 0, false, MUST_EXIST);
        $course = get_course($cmraw->course);
        $videotrack = $DB->get_record('videotrack', ['id' => $cmraw->instance], '*', MUST_EXIST);

        require_login($course, false, $cmraw);
        $cm = \cm_info::create($cmraw);
        $context = \context_module::instance($cm->id);
        self::validate_context($context);
        require_capability('mod/videotrack:view', $context);
        // Learner telemetry is controlled by an explicit participation capability,
        // not by the absence of report access. This supports custom and dual-role
        // learners while keeping ordinary teacher/admin previews non-tracking.
        if (!\mod_videotrack\local\learner_scope::can_participate($context)) {
            throw new \moodle_exception('error:learnertrackingstaff', 'mod_videotrack');
        }

        return [
            'course' => $course,
            'videotrack' => $videotrack,
            'cm' => $cm,
            'context' => $context,
        ];
    }
}
